#!/bin/bash
# Local reflection of .github/workflows/ci.yml — same commands, same order.
# The iOS job is stubbed out there, so nothing here runs iosSimulatorArm64Test either.
set -e

./gradlew :shared:testAndroidHostTest :server:test detekt --parallel
# The spec is generated by the test run — a diff means the committed one is behind the code.
git diff --exit-code -- contracts/openapi.json
TZ=UTC ./gradlew :androidApp:verifyRoborazziDebug
